'use strict';
const COMPONENTS={windings:{name:'Core & windings',code:'TR-01 / WDG',desc:'Active assembly · Internal insulation system'},cooling:{name:'Cooling system',code:'TR-01 / CLG',desc:'Forced-oil / forced-water cooling'},bushings:{name:'HV / LV bushings',code:'TR-01 / BSH',desc:'Single phase · H1/H2 high voltage · X1/X2 low voltage'},tank:{name:'Main tank & oil',code:'TR-01 / TNK',desc:'Insulating oil · Main enclosure'},conservator:{name:'Conservator',code:'TR-01 / CNS',desc:'Oil expansion vessel · Preservation system'},tapchanger:{name:'Tap changer',code:'TR-01 / LTC',desc:'Voltage regulation · Switching assembly'}};
