const sampleSpecs=TAG_CATALOG.map(([tag,name,component,a,p,unit])=>[tag,name,component,a,p,unit]);
function demoData(){const sensors=[];for(let i=0;i<25;i++)for(let j=0;j<sampleSpecs.length;j++){const [tag,name,component,a,p,unit]=sampleSpecs[j];const shift=i===24?0:(Math.sin(i*.47+j)*.012-(24-i)*.001)*Math.abs(a);sensors.push({timestamp:new Date(Date.UTC(2026,10,16,16)-(24-i)*3600000).toISOString(),tag,name,component,actual:+(a+shift).toFixed(3),predicted:+(p+shift*.5).toFixed(3),unit,severity:'normal',advisory:'',advisoryIndication:'',diagnosticAdvisoryIndication:'',advisoryActive:false,diagnosticActive:false,indicationMode:'text'})}return {sensors,health:[],maintenance:Object.keys(COMPONENTS).flatMap((component,i)=>[{component,type:'instruction',title:COMPONENTS[component].name+' inspection guide',date:'2026-09-01',reference:'DEMO-MI-0'+(i+1),content:'Upload the maintenance instructions for '+COMPONENTS[component].name.toLowerCase()+'.'},{component,type:'history',title:['Thermal inspection completed','Cooling bank service','Bushing inspection completed','Oil sample collected','Oil preservation inspection','Tap changer inspection'][i],date:'2026-10-'+(12+i),reference:'DEMO-WO-'+(1042+i),content:'Upload the service report to view inspection findings and work completed.'}]),imports:[],source:'Sample workbook',demo:true}}
