// Apply the confirmed rate unit to previously imported catalog tags with no unit.
for(const row of data.sensors){const known=catalogTag(row.tag)||catalogTag(row.name);if(!row.unit&&known?.[6]==='DGA rates of change')row.unit='ppm/month';}
