let modelView='3d';
let page='overview',component='windings',selectedTag='WTI-01',stamp='',search='',filter='all',overlay=true,libraryFilter='all',pending=null,toastTimer;
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('en-CA',{maximumFractionDigits:2});
const dateLabel=v=>v?new Date(v).toLocaleString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}):'No timestamp';
const dateOnly=v=>v?new Date(v).toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric'}):'Not dated';
