  const tags=modelTagRows(id,rows),shown=tags.slice(0,3);
  return `<div class="model-hover-heading">${esc(COMPONENTS[id].name)}</div><div class="model-hover-source">${data.demo?'Demo data':'Imported data'} · Actual</div>${shown.length?shown.map(r=>`<div class="model-hover-row"><div><span>${esc(r.name||r.tag)}</span><strong>${modelTagValue(r)}</strong></div><small>${esc(r.tag)}${r.unit?'':' · Unit not supplied'}</small><small>${dateLabel(r.timestamp)} UTC</small></div>`).join(''):'<p class="model-hover-empty">No mapped readings.</p>'}${id==='windings'&&tags.length?'<p class="model-hover-note">Shared winding tags; individual HV/LV coil readings are not mapped.</p>':''}${tags.length>shown.length?`<div class="model-hover-footer">+${tags.length-shown.length} more tags</div>`:''}`;
