function sensorTable(){const rows=snapshot().filter(r=>(filter==='all'||r.component===filter)&&`${r.tag} ${r.name}`.toLowerCase().includes(search.toLowerCase()));return `<div class="table-wrap"><table class="sensor-readings"><colgroup><col style="width:35%"><col style="width:12%"><col style="width:12%"><col style="width:41%"></colgroup><thead><tr><th>TAG / MEASUREMENT</th><th>ACTUAL</th><th>ESTIMATE</th><th>ADVISORIES</th></tr></thead><tbody>${rows.map(r=>`<tr data-sensor="${esc(r.tag)}" tabindex="0" role="button" aria-label="View ${esc(r.name||r.tag)}"><td><span>${esc(r.name||r.tag)}</span><small class="table-tag">${esc(r.tag)}</small><small>${COMPONENTS[r.component].name}</small><small>${dateLabel(r.timestamp)} UTC</small></td><td class="numeric">${fmt(r.actual)} <span class="muted">${esc(r.unit)}</span></td><td class="numeric">${fmt(r.predicted)} <span class="muted">${esc(r.unit)}</span></td><td>${combinedAdvisories(r)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No matching tags.</div>'}</div><div class="table-bottom">${rows.length} tags</div>`}
const ALARM_SETTINGS_KEY='field-twin-dga-limits-v1';
let alarmSettings;try{alarmSettings=JSON.parse(localStorage.getItem(ALARM_SETTINGS_KEY))||{};if(typeof alarmSettings!=='object'||Array.isArray(alarmSettings))alarmSettings={};}catch{alarmSettings={};}
function alarmConfig(tag,unit){const c=alarmSettings[tag];return c&&c.unit===(unit||'')?c:null;}
function limitState(row){
  if(!row)return {label:'No reading',level:'unknown'};
  const c=alarmConfig(row.tag,row.unit);
  if(!c||!c.enabled||(c.warning===null&&c.alarm===null))return {label:'Not configured',level:'unknown'};
  if(typeof row.actual!=='number'||!Number.isFinite(row.actual))return {label:'No reading',level:'unknown'};
  if(Number.isFinite(c.alarm)&&row.actual>=c.alarm)return {label:'Alarm',level:'critical'};
  if(Number.isFinite(c.warning)&&row.actual>=c.warning)return {label:'Warning',level:'watch'};
  return {label:'Within limits',level:'normal'};
}
function limitBadge(row){const state=limitState(row);return badge(state.level,state.label);}
function alarmTags(){const mapping=dgaMapping(),latest=new Map();for(const r of data.sensors){if(!latest.has(r.tag)||r.timestamp>latest.get(r.tag).timestamp)latest.set(r.tag,r);}return DGA_CATALOG.map(c=>({channel:c[0],name:c[1],tag:mapping[c[0]]||'',row:latest.get(mapping[c[0]]),unit:latest.has(mapping[c[0]])?(latest.get(mapping[c[0]]).unit||''):c[5]}));}
function settingsPage(){return heading('Settings','DGA alarm limits')+`<section class="panel"><div class="panel-head"><h2>Gas tag limits</h2></div><div class="alarm-settings-intro">Set upper warning and alarm limits for each mapped tag. A reading triggers at or above the limit. Blank limits are disabled; no default limits are assumed. Limits use the displayed tag units and apply to actual readings at the selected snapshot or replay time. These local alarms are separate from imported source advisories.</div><form id="alarm-settings-form"><div class="table-wrap"><table class="alarm-settings-table"><thead><tr><th>Gas / tag</th><th>Units</th><th>Enabled</th><th>Warning ≥</th><th>Alarm ≥</th></tr></thead><tbody>${alarmTags().map((t,i)=>{const c=alarmConfig(t.tag,t.unit)||{enabled:false,warning:null,alarm:null};return `<tr data-alarm-row="${i}"><td>${esc(t.name)}<small>${esc(t.tag||'Not mapped — configure in DGA monitoring')}</small></td><td>${esc(t.unit||'Not supplied')}</td><td><input type="checkbox" data-limit="enabled" aria-label="Enable ${esc(t.name)} limits" ${c.enabled?'checked':''} ${t.tag?'':'disabled'}></td>${['warning','alarm'].map(k=>`<td><input type="number" step="any" data-limit="${k}" aria-label="${k} limit for ${esc(t.name)}" value="${Number.isFinite(c[k])?c[k]:''}" placeholder="Off" ${t.tag?'':'disabled'}></td>`).join('')}</tr>`;}).join('')}</tbody></table></div><div class="alarm-settings-actions"><p id="alarm-settings-error" role="alert"></p><button class="btn primary" type="submit">Save limits</button><span class="muted">Saved in this browser.</span></div></form></section>`;}
function validateAlarmLimit(enabled,warning,alarm){
  if([warning,alarm].some(v=>v!==null&&!Number.isFinite(v)))return 'Enter finite numeric limits.';
  if(enabled&&warning===null&&alarm===null)return 'Enter at least one limit or disable this tag.';
  if(warning!==null&&alarm!==null&&warning>=alarm)return 'The alarm limit must be greater than the warning limit.';
  return '';
}
function bindAlarmSettings(){const form=$('#alarm-settings-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();const tags=alarmTags(),next={...alarmSettings};let error='';form.querySelectorAll('[data-alarm-row]').forEach(el=>{const t=tags[Number(el.dataset.alarmRow)];if(!t.tag)return;const enabled=el.querySelector('[data-limit="enabled"]').checked,read=k=>{const value=el.querySelector(`[data-limit="${k}"]`).value.trim();return value===''?null:Number(value);},warning=read('warning'),alarm=read('alarm');const issue=validateAlarmLimit(enabled,warning,alarm);if(issue&&!error)error=t.name+': '+issue;Object.defineProperty(next,t.tag,{value:{unit:t.unit||'',enabled,warning,alarm},enumerable:true,configurable:true,writable:true});});if(error){$('#alarm-settings-error').textContent=error;return;}try{localStorage.setItem(ALARM_SETTINGS_KEY,JSON.stringify(next));alarmSettings=next;$('#alarm-settings-error').textContent='';notify('DGA alarm limits saved.');}catch{$('#alarm-settings-error').textContent='Could not save limits. Browser storage is unavailable or full.';}};}
function trendStack(tags=[...new Map(data.sensors.map(r=>[r.tag,r])).values()],until=stamp||timestamps().at(-1)){
  const grouped=new Map();for(const row of data.sensors){if(!grouped.has(row.tag))grouped.set(row.tag,[]);grouped.get(row.tag).push(row);}
  return `<div class="trend-stack" aria-label="All tag trends">${tags.map(r=>`<section class="panel tag-trend" data-trend-tag="${esc(r.tag)}"><div class="panel-head"><div><h2>${esc(r.name||r.tag)}</h2><p class="sub">${esc(r.tag)}</p></div><span class="muted">24 hours · UTC</span></div>${chart(r.tag,until,grouped.get(r.tag)||[])}</section>`).join('')||'<div class="empty">No tags imported.</div>'}</div>`;
}
function scrollToTrend(tag){[...document.querySelectorAll('[data-trend-tag]')].find(el=>el.dataset.trendTag===tag)?.scrollIntoView({behavior:'smooth',block:'center'});}
function chart(tag=selectedTag,until=stamp||timestamps().at(-1),readings=data.sensors){const end=new Date(until).getTime();const history=readings.filter(r=>r.tag===tag&&Date.parse(r.timestamp)<=end).sort((a,b)=>a.timestamp.localeCompare(b.timestamp));const current=history.at(-1);const points=history.filter(r=>Date.parse(r.timestamp)>=end-86400000);if(!points.length)return '<div class="empty">No readings in this period.</div>';let lo=Math.min(...points.flatMap(r=>[r.actual,r.predicted])),hi=Math.max(...points.flatMap(r=>[r.actual,r.predicted]));const pad=Math.max((hi-lo)*.12,Math.abs(hi)*.001,.000001);lo-=pad;hi+=pad;const width=typeof document==='undefined'?1100:Math.max(280,((document.querySelector('main')?.clientWidth||1200)-72-(window.innerWidth>1050?10:0))/(window.innerWidth>1050?2:1)-26),plotWidth=width-65;const x=r=>45+(new Date(r.timestamp).getTime()-(end-86400000))/86400000*plotWidth,y=v=>92-(v-lo)/(hi-lo)*84,path=k=>points.map((r,i)=>(i?'L':'M')+x(r).toFixed(2)+','+y(r[k]).toFixed(2)).join(' ');return `<div class="chart-wrap"><div class="chart-summary"><span><i class="trace-key"></i>Actual <b>${fmt(current.actual)}</b> ${esc(current.unit)}</span><span><i class="trace-key predicted"></i>Estimate <b>${fmt(current.predicted)}</b> ${esc(current.unit)}</span>${alarmConfig(tag,current.unit)?.enabled?limitBadge(current):''}<span class="chart-samples">n = ${points.length} · ${dateOnly(new Date(end-86400000).toISOString())} – ${dateOnly(until)}</span></div><svg class="chart-svg" viewBox="0 0 ${width} 116" role="img" aria-label="Actual and estimate ${esc(current.name||current.tag)} over the last 24 hours"><title>Actual and estimate readings. Current actual ${fmt(current.actual)}, estimate ${fmt(current.predicted)} ${esc(current.unit)}.</title>${[0,1,2,3].map(i=>{const v=lo+(hi-lo)*i/3;return `<path d="M45 ${y(v)}H${width-20}" stroke="#e0e5ea" stroke-width="0.7"/><text x="33" y="${y(v)+4}" text-anchor="end" font-size="9" fill="#536170">${v!==0&&(Math.abs(v)<.01||Math.abs(v)>=100000)?v.toExponential(1):Number(v.toPrecision(4)).toString()}</text>`}).join('')}${[0,6,12,18,24].map(i=>`<path d="M${45+i/24*plotWidth} 8V92" stroke="#e0e5ea" stroke-width="0.7"/>`).join('')}<path d="M45 8V92H${width-20}" stroke="#85919c" stroke-width="0.8" fill="none"/><path d="${path('predicted')}" stroke="#b56e25" stroke-width="1.3" stroke-dasharray="5 5" fill="none"/><path d="${path('actual')}" stroke="#245b8a" stroke-width="1.5" fill="none"/>${points.map(r=>`<circle cx="${x(r)}" cy="${y(r.actual)}" r="${points.length===1?3:1.2}" fill="#245b8a"><title>${dateLabel(r.timestamp)} UTC — Actual ${r.actual}; estimate ${r.predicted} ${esc(r.unit)}</title></circle>`).join('')}${[0,6,12,18,24].map(i=>`<text x="${45+i/24*plotWidth}" y="108" text-anchor="middle" font-size="9" fill="#536170">${new Date(end-86400000+i*3600000).toISOString().slice(11,16)}</text>`).join('')}</svg></div>`}
function libraryPage(){if(typeof maintenanceLibraryPage==='function')return maintenanceLibraryPage();const records=data.maintenance.filter(r=>libraryFilter==='all'||r.component===libraryFilter);return heading('Maintenance library','',`<button class="btn primary" data-action="imports">↥ &nbsp; Import records</button>`)+`${data.demo?'<p class="data-source">Demo data</p>':''}<section class="panel"><div class="panel-head"><h2>Maintenance documents <span class="muted">(${records.length})</span></h2><select id="library-component" aria-label="Maintenance component"><option value="all">All components</option>${componentOptions(libraryFilter)}</select></div><div class="library-list">${records.map(r=>`<div class="library-item"><div><h3>${esc(r.title)}</h3><p>${COMPONENTS[r.component]?.name||'Transformer'} · ${dateOnly(r.date)}<br><span class="table-tag">${esc(r.reference||'No reference supplied')}</span></p></div><button class="btn" data-record="${data.maintenance.indexOf(r)}">View ↗</button></div>`).join('')||'<div class="empty">No matching documents.</div>'}</div></section>`}
function openDetail(){if(typeof maintenanceLibraryPage==='function'){libraryFilter=component==='tank'?'tank-oil':component;maintenanceState.query='';maintenanceState.selection={kind:'folder',path:''};go('maintenance');return;}const c=COMPONENTS[component],body=data.maintenance.filter(r=>r.component===component).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(recordMarkup).join('')||'<p class="empty">No documents imported.</p>';showModal(c.name+' · Maintenance documents',body)}
