function bindImport(){if(pending?.mode==='smart'){bindSmart();return;}if($('#switch-smart'))$('#switch-smart').onclick=()=>{pending=initSmart(pending.book,pending.file);render();};if(!$('#sheet-select'))return;$('#sheet-select').onchange=e=>{pending.sheet=e.target.value;const match=Object.keys(SCHEMAS).find(t=>norm(t)===norm(pending.sheet));if(match)pending.type=match;loadSheet();render()};$('#dataset-type').onchange=e=>{pending.type=e.target.value;inferMap();render()};$('#cancel-import').onclick=()=>{pending=null;render()};document.querySelectorAll('[data-map]').forEach(s=>s.onchange=()=>{pending.map[s.dataset.map]=s.value;$('#validation').innerHTML=validationView();$('#apply-import').onclick=applyImport});if($('#apply-import'))$('#apply-import').onclick=applyImport}
